from abc import ABCMeta, abstractmethod
from collections import OrderedDict
import lxml.etree as ET
import six
from taf.internal.core import Group


class NamedComponent(object):
    """
    An object, that has a name.

    A named component can either be a single named object
    or a group of named components.
    """

    def __init__(self, name, **kwargs):
        """
        Create a named component.

        :param str name:
            name of the component (it must be a name, that can be used as directory name,
            XML tag and is unique among all named objects)
        """
        super(NamedComponent, self).__init__(**kwargs)
        self._name = name

    @property
    def name(self):
        """
        Name.

        :return: name
        :rtype: str
        """
        return self._name


class NamedObject(NamedComponent):
    """
    Named object.
    """

    def accept(self, visitor):
        visitor.visitNamedObject(self)


class NamedGroup(NamedComponent, Group):
    """
    Group of named components.
    """

    def __init__(self, **kwargs):
        """
        Create a group of named members.
        """
        super(NamedGroup, self).__init__(**kwargs)
        self._member_dict = OrderedDict(
            zip(
                [member.name for member in self._members],
                self._members))

    def __getitem__(self, item):
        """
        Return member with a certain name.

        :param str item: member name
        :return: member
        :rtype NamedComponent:
        """
        return self._member_dict[item]

    def findall(self, xpath):
        """
        Find all named components for a given XPath.

        The XML tree, which is searched through, is created from
        the names of the named components as XML tags.
        Members are represented as child nodes.

        :param xpath:
        :return:

.. code-block:: Robot

        Usage example:

            from taf.collectors.core.entities.named import *
            named_object1= NamedObject(name="named_object1")
            named_object2= NamedObject(name="named_object2")
            named_object3= NamedObject(name="named_object3")
            named_group2 = NamedGroup(name="named_group2", members=[named_object1, named_object2])
            named_group3 = NamedGroup(name="named_group3", members=[named_object2, named_object3])
            named_group1 = NamedGroup(name="named_group1", members=[named_group2, named_group3])
            print([element.name for element in named_group1.findall(".//*")])

        Result:

            ['named_group2', 'named_object1', 'named_object2', 'named_group3', 'named_object2', 'named_object3']

        """
        visitor = XPathAccessVisitor()
        self.accept(visitor)
        return visitor.findall(xpath=xpath)

    def accept(self, visitor):
        visitor.visitNamedGroup(self)


@six.add_metaclass(ABCMeta)
class Visitor(object):
    """
    Visitor for NamedComponents.
    """

    @abstractmethod
    def visitNamedObject(self, named_object):
        pass

    @abstractmethod
    def visitNamedGroup(self, named_group):
        pass


class XPathAccessVisitor(Visitor):
    """
    Visit a tree of NamedComponents and allow accessing its nodes via findall(xpath) on the visit result.
    """

    def __init__(self, **kwargs):
        super(XPathAccessVisitor, self).__init__(**kwargs)
        self._id_dict = {}
        self._root = None
        self._parent = None

    def visitNamedObject(self, named_object):
        id_ = str(id(named_object))
        self._id_dict[id_] = named_object
        ET.SubElement(self._parent, named_object.name, attrib={'id': id_})

    def visitNamedGroup(self, named_group):
        id_ = str(id(named_group))
        self._id_dict[id_] = named_group
        element = ET.Element(named_group.name, attrib={'id': id_})
        if self._parent is None:
            self._root = element
        else:
            self._parent.append(element)
        for member in named_group.members:
            self._parent = element
            member.accept(self)

    def findall(self, xpath):
        return [self._id_dict[element.get("id")] for element in self._root.xpath(xpath)]
